      <!-- Encoder to Decoder Connection -->
      <path d="M100 180 H200 V280 H250" stroke="var(--color-border-info)" stroke-width="2" stroke-dasharray="4 2" marker-end="url(#arrowhead)"/>

      <!-- Inputs -->
      <g class="node" onclick="showDetail('input_emb')">
