<script>
  const data = {
    input_emb: {
      title: "输入嵌入 (Input Embedding)",
      tag: "输入层",
      tagClass: "c-gray",
      formula: "Embedding(x) → Vector",
      desc: "将离散的单词（Token）转换为连续的低维稠密向量，捕捉单词间的语义关系。",
      features: ["词表映射", "维度固定 (d_model)", "语义对齐"]
    },
    pos_enc: {
      title: "位置编码 (Positional Encoding)",
      tag: "辅助层",
      tagClass: "c-amber",
      formula: "PE(pos, 2i) = sin(pos / 10000^(2i/d_model))",
      desc: "由于 Transformer 没有循环或卷积结构，无法感知顺序。位置编码通过正弦/余弦函数为每个 Token 注入位置信息。",
      features: ["绝对位置感知", "相对距离表达", "无需训练参数"]
    },
    mha_enc: {
      title: "多头自注意力 (Multi-Head Attention)",
      tag: "核心组件",
      tagClass: "c-purple",
      formula: "Attention(Q, K, V) = softmax(QKᵀ / √dₖ)V",
      desc: "允许模型在处理一个单词时，同时“关注”句子中其他位置的信息。多头机制让模型能从多个子空间学习不同的依赖关系。",
      features: ["并行计算", "长距离依赖建模", "全局感受野"]
    },
    masked_mha: {
      title: "掩码多头注意力 (Masked MHA)",
      tag: "解码组件",
      tagClass: "c-teal",
      formula: "Mask(QKᵀ) → -∞ for future tokens",
      desc: "在解码时，防止模型看到“未来”的信息。通过掩码机制，确保预测第 i 个单词时只能看到前 i-1 个单词。",
      features: ["自回归约束", "因果关系保护", "训练并行化"]
    },
    cross_mha: {
      title: "交叉注意力 (Encoder-Decoder Attention)",
      tag: "桥接组件",
      tagClass: "c-teal",
      formula: "Q from Decoder, K/V from Encoder",
      desc: "解码器通过此层访问编码器的输出。这使得解码器在生成目标单词时，能够参考输入序列的完整上下文。",
      features: ["源序列对齐", "跨模态/语言交互", "信息传递枢纽"]
    },
    ffn: {
      title: "前馈网络 (Feed Forward Network)",
      tag: "处理层",
      tagClass: "c-purple",
      formula: "FFN(x) = max(0, xW₁ + b₁)W₂ + b₂",
      desc: "对每个位置的向量进行独立的非线性变换。通常由两个线性层和一个 ReLU 激活函数组成。",
      features: ["逐位置处理", "特征维度扩张", "非线性增强"]
    },
    output: {
      title: "输出层 (Linear & Softmax)",
      tag: "输出层",
      tagClass: "c-coral",
      formula: "P = softmax(Linear(x))",
      desc: "将解码器的输出映射回词表大小的维度，并通过 Softmax 函数计算每个单词出现的概率分布。",
      features: ["概率预测", "词表映射", "贪婪/束搜索基础"]
    }
  };

  function showDetail(id) {
    const item = data[id];
    if (!item) return;

    document.getElementById('empty-state').style.display = 'none';
    document.getElementById('content-state').style.display = 'block';

    document.getElementById('detail-title').innerText = item.title;
    document.getElementById('detail-tag').innerText = item.tag;
    document.getElementById('detail-tag').className = 'label-tag ' + item.tagClass;
    document.getElementById('detail-formula').innerText = item.formula;
    document.getElementById('detail-desc').innerText = item.desc;

    const list = document.getElementById('detail-features');
    list.innerHTML = '';
    item.features.forEach(f => {
      const li = document.createElement('li');
      li.innerText = f;
      list.appendChild(li);
    });
  }
</script>
</widget_code>

