<widget_code>
<style>
  :root {
    --p-800: #3C3489;
    --p-100: #CECBF6;
    --a-400: #EF9F27;
    --g-100: #D3D1C7;
  }

  #widget-container {
    font-family: var(--font-sans);
    color: var(--color-text-primary);
    padding: 1rem;
    display: flex;
    flex-direction: column;
    gap: 1rem;
  }

  .controls-row {
    display: flex;
    align-items: center;
    gap: 20px;
    background: var(--color-background-secondary);
    padding: 12px 16px;
    border-radius: var(--border-radius-lg);
    border: 1px solid var(--color-border-tertiary);
  }

  .control-group {
    display: flex;
    flex-direction: column;
    gap: 4px;
  }

  label {
    font-size: 12px;
    color: var(--color-text-secondary);
    font-weight: 500;
  }

  select, input[type="range"] {
    background: var(--color-background-primary);
    border: 1px solid var(--color-border-primary);
    border-radius: 4px;
    padding: 4px 8px;
    color: var(--color-text-primary);
    font-size: 14px;
  }

  #viz-canvas {
    flex: 1;
    min-height: 280px;
    background: var(--color-background-primary);
    border-radius: var(--border-radius-lg);
    border: 1px solid var(--color-border-tertiary);
    position: relative;
    overflow: hidden;
  }

  .token-node {
    cursor: pointer;
    transition: transform 0.2s;
  }
  .token-node:hover {
    transform: translateY(-2px);
  }

  .heatmap-container {
    display: flex;
    flex-direction: column;
    gap: 8px;
    padding: 12px;
    background: var(--color-background-secondary);
    border-radius: var(--border-radius-lg);
  }

  .heatmap-grid {
    display: grid;
    gap: 2px;
  }

  .heatmap-cell {
    width: 24px;
    height: 24px;
    border-radius: 2px;
    transition: background 0.3s;
  }

  .legend {
    display: flex;
    align-items: center;
    gap: 12px;
    font-size: 12px;
    color: var(--color-text-secondary);
  }

  .legend-item {
    display: flex;
    align-items: center;
    gap: 4px;
  }

  .color-box {
    width: 12px;
    height: 12px;
    border-radius: 2px;
  }
</style>

<div id="widget-container">
  <div class="controls-row">
    <div class="control-group">
      <label>示例句子</label>
      <select id="sentence-select">
        <option value="0">Transformer 正在 改变 机器 翻译</option>
        <option value="1">自注意力 机制 是 核心 所在</option>
        <option value="2">深度 学习 推动 了 技术 进步</option>
      </select>
    </div>
    <div class="control-group" style="flex: 1;">
      <label>注意力锐度 (Temperature): <span id="temp-val">1.0</span></label>
      <input type="range" id="temp-slider" min="0.1" max="3.0" step="0.1" value="1.0">
    </div>
  </div>

  <div id="viz-canvas">
    <svg id="main-svg" width="100%" height="100%" viewBox="0 0 680 300">
      <defs>
        <marker id="arrow" viewBox="0 0 10 10" refX="8" refY="5" markerWidth="4" markerHeight="4" orient="auto-start-reverse">
          <path d="M2 1L8 5L2 9" fill="none" stroke="context-stroke" stroke-width="1.5" stroke-linecap="round"/>
        </marker>
      </defs>
      <g id="lines-group"></g>
      <g id="tokens-group"></g>
    </svg>
  </div>

  <div class="heatmap-container">
    <div style="display: flex; justify-content: space-between; align-items: center;">
      <label>注意力权重矩阵 (Attention Matrix)</label>
      <div class="legend">
        <div class="legend-item"><div class="color-box" style="background: var(--p-100)"></div><span>低权重</span></div>
        <div class="legend-item"><div class="color-box" style="background: var(--a-400)"></div><span>高权重</span></div>
      </div>
    </div>
    <div id="heatmap" class="heatmap-grid"></div>
  </div>
</div>

<script>
  const sentences = [
    ["Transformer", "正在", "改变", "机器", "翻译"],
    ["自注意力", "机制", "是", "核心", "所在"],
    ["深度", "学习", "推动", "了", "技术", "进步"]
  ];

  // Simulated raw scores (logits) to create interesting patterns
  const baseScores = [
    [
      [5, 2, 4, 1, 1],
      [1, 4, 2, 1, 1],
      [3, 2, 5, 2, 2],
      [1, 1, 2, 4, 5],
      [1, 1, 2, 5, 4]
    ],
    [
      [5, 4, 1, 2, 1],
      [4, 5, 1, 1, 1],
      [1, 1, 4, 2, 2],
      [2, 1, 2, 5, 3],
      [1, 1, 2, 3, 5]
    ],
    [
      [5, 4, 2, 1, 2, 1],
      [4, 5, 2, 1, 1, 1],
      [2, 2, 5, 3, 2, 4],
      [1, 1, 3, 4, 1, 1],
      [2, 1, 2, 1, 5, 3],
      [1, 1, 4, 1, 3, 5]
    ]
  ];

  let currentIdx = 0;
  let selectedToken = 0;
  let temperature = 1.0;

  const sentenceSelect = document.getElementById('sentence-select');
  const tempSlider = document.getElementById('temp-slider');
  const tempVal = document.getElementById('temp-val');
  const tokensGroup = document.getElementById('tokens-group');
  const linesGroup = document.getElementById('lines-group');
  const heatmap = document.getElementById('heatmap');

  function softmax(logits, temp) {
    const exps = logits.map(v => Math.exp(v / temp));
    const sum = exps.reduce((a, b) => a + b, 0);
    return exps.map(v => v / sum);
  }

  function update() {
    const tokens = sentences[currentIdx];
    const scores = baseScores[currentIdx];
    const n = tokens.length;

    // Update UI
    tempVal.textContent = temperature.toFixed(1);

    // Clear
    tokensGroup.innerHTML = '';
    linesGroup.innerHTML = '';
    heatmap.innerHTML = '';
    heatmap.style.gridTemplateColumns = `repeat(${n}, 24px)`;

    const spacing = 600 / (n - 1 || 1);
    const startX = (680 - (n - 1) * spacing) / 2;

    // Calculate weights for all pairs for heatmap
    const allWeights = scores.map(row => softmax(row, temperature));

    // Draw Heatmap
    allWeights.forEach((row, i) => {
      row.forEach((w, j) => {
        const cell = document.createElement('div');
        cell.className = 'heatmap-cell';
        const alpha = Math.max(0.1, w * n * 0.5);
        cell.style.background = `rgba(239, 159, 39, ${alpha})`;
        cell.title = `从 ${tokens[i]} 到 ${tokens[j]}: ${(w * 100).toFixed(1)}%`;
        heatmap.appendChild(cell);
      });
    });

    // Draw Tokens
    tokens.forEach((text, i) => {
      const x = startX + i * spacing;
      const y = 240;

      const g = document.createElementNS('http://www.w3.org/2000/svg', 'g');
      g.setAttribute('class', 'token-node');
      g.onclick = () => { selectedToken = i; update(); };

      const rect = document.createElementNS('http://www.w3.org/2000/svg', 'rect');
      rect.setAttribute('x', x - 40);
      rect.setAttribute('y', y - 20);
      rect.setAttribute('width', 80);
      rect.setAttribute('height', 40);
      rect.setAttribute('rx', 8);
      rect.setAttribute('fill', i === selectedToken ? 'var(--p-800)' : 'var(--color-background-secondary)');
      rect.setAttribute('stroke', i === selectedToken ? 'var(--p-800)' : 'var(--color-border-primary)');
      rect.setAttribute('stroke-width', '1');

      const txt = document.createElementNS('http://www.w3.org/2000/svg', 'text');
      txt.setAttribute('x', x);
      txt.setAttribute('y', y);
      txt.setAttribute('text-anchor', 'middle');
      txt.setAttribute('dominant-baseline', 'central');
      txt.setAttribute('fill', i === selectedToken ? '#fff' : 'var(--color-text-primary)');
      txt.style.fontSize = '14px';
      txt.style.fontWeight = i === selectedToken ? '500' : '400';
      txt.textContent = text;

      g.appendChild(rect);
      g.appendChild(txt);
      tokensGroup.appendChild(g);
    });

    // Draw Attention Lines for selected token
    const weights = allWeights[selectedToken];
    const queryX = startX + selectedToken * spacing;
    const queryY = 220;

    weights.forEach((w, i) => {
      const targetX = startX + i * spacing;
      const targetY = 220;

      const path = document.createElementNS('http://www.w3.org/2000/svg', 'path');
      // Curve up and back down
      const midY = 80;
      const d = `M ${queryX} ${queryY} C ${queryX} ${midY}, ${targetX} ${midY}, ${targetX} ${targetY}`;

      path.setAttribute('d', d);
      path.setAttribute('fill', 'none');
      path.setAttribute('stroke', 'var(--a-400)');
      path.setAttribute('stroke-width', Math.max(0.5, w * 12));
      path.setAttribute('opacity', Math.max(0.05, w * 1.5));
      path.setAttribute('marker-end', w > 0.1 ? 'url(#arrow)' : '');

      linesGroup.appendChild(path);
    });

    // Add labels for Query/Key
    const qLabel = document.createElementNS('http://www.w3.org/2000/svg', 'text');
    qLabel.setAttribute('x', queryX);
    qLabel.setAttribute('y', 275);
    qLabel.setAttribute('text-anchor', 'middle');
    qLabel.setAttribute('fill', 'var(--p-800)');
    qLabel.style.fontSize = '10px';
    qLabel.style.fontWeight = '500';
    qLabel.textContent = '查询 (Query)';
    tokensGroup.appendChild(qLabel);
  }

  sentenceSelect.onchange = (e) => {
    currentIdx = parseInt(e.target.value);
    selectedToken = 0;
    update();
  };

  tempSlider.oninput = (e) => {
    temperature = parseFloat(e.target.value);
    update();
  };

  // Initial render
  update();
</script>
