<script>
  const canvas = document.getElementById('canvas');
  const ctx = canvas.getContext('2d');
  const powerSwitch = document.getElementById('power-switch');
  const indicatorSwitch = document.getElementById('indicator-switch');
  const currentVal = document.getElementById('current-val');
  const phVal = document.getElementById('ph-val');

  let powerOn = false;
  let indicatorOn = false;
  let ph = 7.0;
  let current = 0.0;
  let pinkIntensity = 0;

  const ions = [];
  const bubbles = [];
  const ionTypes = [
    { label: 'Na+', color: '#2196f3', size: 6 },
    { label: 'Cl-', color: '#8bc34a', size: 7 },
    { label: 'H+', color: '#ffeb3b', size: 4 },
    { label: 'OH-', color: '#e040fb', size: 5 }
  ];

  // Initialize ions
  for (let i = 0; i < 40; i++) {
    const typeIdx = i < 15 ? 0 : (i < 30 ? 1 : (i < 35 ? 2 : 3));
    ions.push({
      x: 80 + Math.random() * 280,
      y: 150 + Math.random() * 200,
      vx: (Math.random() - 0.5) * 1,
      vy: (Math.random() - 0.5) * 1,
      type: ionTypes[typeIdx]
    });
  }

  function drawBeaker() {
    // Water
    ctx.fillStyle = '#e3f2fd';
    ctx.fillRect(60, 140, 320, 220);

    // Phenolphthalein effect
    if (indicatorOn && pinkIntensity > 0) {
      const grad = ctx.createRadialGradient(320, 250, 10, 320, 250, 120);
      grad.addColorStop(0, `rgba(255, 0, 150, ${pinkIntensity * 0.4})`);
      grad.addColorStop(1, 'rgba(255, 0, 150, 0)');
      ctx.fillStyle = grad;
      ctx.fillRect(60, 140, 320, 220);
    }

    // Beaker outline
    ctx.strokeStyle = '#90a4ae';
    ctx.lineWidth = 3;
    ctx.beginPath();
    ctx.moveTo(60, 100);
    ctx.lineTo(60, 360);
    ctx.lineTo(380, 360);
    ctx.lineTo(380, 100);
    ctx.stroke();

    // Electrodes
    // Anode (+)
    ctx.fillStyle = '#546e7a';
    ctx.fillRect(100, 80, 20, 240);
    ctx.fillStyle = powerOn ? '#ff5252' : '#90a4ae';
    ctx.font = 'bold 14px sans-serif';
    ctx.fillText('+', 105, 75);
    ctx.fillText('阳极', 95, 60);

    // Cathode (-)
    ctx.fillStyle = '#546e7a';
    ctx.fillRect(320, 80, 20, 240);
    ctx.fillStyle = powerOn ? '#448aff' : '#90a4ae';
    ctx.fillText('-', 325, 75);
    ctx.fillText('阴极', 315, 60);

    // Wires
    ctx.strokeStyle = '#455a64';
    ctx.lineWidth = 2;
    ctx.beginPath();
    ctx.moveTo(110, 80);
    ctx.lineTo(110, 40);
    ctx.lineTo(330, 40);
    ctx.lineTo(330, 80);
    ctx.stroke();

    // Power Source
    ctx.fillStyle = '#ffffff';
    ctx.fillRect(200, 25, 40, 30);
    ctx.strokeRect(200, 25, 40, 30);
    ctx.fillStyle = powerOn ? '#4caf50' : '#f44336';
    ctx.beginPath();
    ctx.arc(220, 40, 5, 0, Math.PI * 2);
    ctx.fill();
  }

  function update() {
    powerOn = powerSwitch.checked;
    indicatorOn = indicatorSwitch.checked;

    if (powerOn) {
      current = Math.min(2.5, current + 0.05);
      ph = Math.min(13.5, ph + 0.01);
      if (indicatorOn) pinkIntensity = Math.min(1, pinkIntensity + 0.005);
    } else {
      current = Math.max(0, current - 0.1);
      // pH and pink stay unless reset (simplified)
    }

    currentVal.textContent = current.toFixed(2);
    phVal.textContent = ph.toFixed(1);

    // Update Ions
    ions.forEach(ion => {
      if (powerOn) {
        // Drift
        if (ion.type.label === 'Cl-' || ion.type.label === 'OH-') {
          ion.vx -= 0.05; // Move to Anode (Left)
        } else {
          ion.vx += 0.05; // Move to Cathode (Right)
        }
      }

      // Brownian motion
      ion.vx += (Math.random() - 0.5) * 0.2;
      ion.vy += (Math.random() - 0.5) * 0.2;

      // Friction
      ion.vx *= 0.95;
      ion.vy *= 0.95;

      ion.x += ion.vx;
      ion.y += ion.vy;

      // Boundary check
      if (ion.x < 70) ion.vx += 0.5;
      if (ion.x > 370) ion.vx -= 0.5;
      if (ion.y < 150) ion.vy += 0.5;
      if (ion.y > 350) ion.vy -= 0.5;

      // Reaction at electrodes
      if (powerOn) {
        if (ion.x < 125 && ion.x > 95 && ion.type.label === 'Cl-') {
          if (Math.random() > 0.95) {
            bubbles.push({ x: 110 + (Math.random()-0.5)*15, y: ion.y, r: 2 + Math.random()*3, type: 'cl' });
            ion.x = 150 + Math.random() * 100; // Recycle ion
          }
        }
        if (ion.x > 315 && ion.x < 345) {
           if (Math.random() > 0.92) {
             bubbles.push({ x: 330 + (Math.random()-0.5)*15, y: ion.y, r: 2 + Math.random()*2, type: 'h' });
           }
        }
      }
    });

    // Update Bubbles
    for (let i = bubbles.length - 1; i >= 0; i--) {
      bubbles[i].y -= 1.5;
      bubbles[i].x += (Math.random() - 0.5) * 1;
      if (bubbles[i].y < 130) bubbles.splice(i, 1);
    }
  }

  function draw() {
    ctx.clearRect(0, 0, canvas.width, canvas.height);

    drawBeaker();

    // Draw Bubbles
    bubbles.forEach(b => {
      ctx.beginPath();
      ctx.arc(b.x, b.y, b.r, 0, Math.PI * 2);
      ctx.fillStyle = b.type === 'cl' ? 'rgba(139, 195, 74, 0.5)' : 'rgba(200, 230, 255, 0.6)';
      ctx.fill();
      ctx.strokeStyle = 'rgba(255,255,255,0.3)';
      ctx.stroke();
    });

    // Draw Ions
    ions.forEach(ion => {
      ctx.beginPath();
      ctx.arc(ion.x, ion.y, ion.type.size, 0, Math.PI * 2);
      ctx.fillStyle = ion.type.color;
      ctx.fill();
      ctx.fillStyle = '#000';
      ctx.font = '8px sans-serif';
      ctx.textAlign = 'center';
      ctx.textBaseline = 'middle';
      ctx.fillText(ion.type.label, ion.x, ion.y);
    });

    update();
    requestAnimationFrame(draw);
  }

  draw();
</script>
