  ctx.lineTo(width - 80, 340);
  ctx.lineTo(width - 80, 80);
  ctx.stroke();

  // Water level
  ctx.fillStyle = 'rgba(186, 230, 253, 0.3)';
  ctx.fillRect(80, 100, width - 160, 240);

  // Electrodes
  // Anode (+) Left
  ctx.fillStyle = '#334155';
  ctx.fillRect(140, 60, 25, 240);
  ctx.fillStyle = '#ef4444';
  ctx.font = 'bold 14px sans-serif';
  ctx.fillText('+', 148, 55);

  // Cathode (-) Right
  ctx.fillStyle = '#334155';
  ctx.fillRect(width - 165, 60, 25, 240);
  ctx.fillStyle = '#3b82f6';
  ctx.fillText('-', width - 155, 55);

  // Wires
  ctx.strokeStyle = '#475569';
  ctx.lineWidth = 2;
  ctx.beginPath();
  ctx.moveTo(152, 60);
  ctx.lineTo(152, 30);
  ctx.lineTo(width/2 - 20, 30);
  ctx.stroke();

  ctx.beginPath();
  ctx.moveTo(width - 152, 60);
  ctx.lineTo(width - 152, 30);
  ctx.lineTo(width/2 + 20, 30);
  ctx.stroke();

  // Battery symbol
  ctx.fillStyle = powerOn ? '#f59e0b' : '#94a3b8';
  ctx.fillRect(width/2 - 20, 15, 40, 30);
}

function animate() {
  ctx.clearRect(0, 0, width, height);
  drawBeaker();

  // Pink diffusion near cathode
  if (phenActive && powerOn && voltage > 0) {
    pinkIntensity = Math.min(pinkIntensity + 0.001 * voltage, 0.6);
    const grad = ctx.createRadialGradient(width - 152, 220, 10, width - 152, 220, 150);
    grad.addColorStop(0, `rgba(236, 72, 153, ${pinkIntensity})`);
    grad.addColorStop(1, 'rgba(236, 72, 153, 0)');
    ctx.fillStyle = grad;
    ctx.fillRect(80, 100, width - 160, 240);
  }

  // Update and draw ions
  ions.forEach(ion => {
    if (powerOn) {
      // Drift velocity based on charge and voltage
      const drift = (voltage / 10) * ion.type.charge;
      // Anode is at x=140-165, Cathode is at x=width-165 to width-140
      if (ion.type.charge < 0) { // Anions to Anode (Left)
        ion.vx -= 0.05 * (voltage / 5);
      } else { // Cations to Cathode (Right)
        ion.vx += 0.05 * (voltage / 5);
      }
    }

    // Brownian-ish motion
    ion.vx += (Math.random() - 0.5) * 0.2;
    ion.vy += (Math.random() - 0.5) * 0.2;

    // Friction
    ion.vx *= 0.95;
    ion.vy *= 0.95;

    ion.x += ion.vx;
    ion.y += ion.vy;

    // Boundaries
    if (ion.x < 90) ion.x = 90, ion.vx *= -1;
    if (ion.x > width - 90) ion.x = width - 90, ion.vx *= -1;
    if (ion.y < 110) ion.y = 110, ion.vy *= -1;
    if (ion.y > 330) ion.y = 330, ion.vy *= -1;

    // Draw ion
    ctx.beginPath();
    ctx.arc(ion.x, ion.y, 6, 0, Math.PI * 2);
    ctx.fillStyle = ion.type.color;
    ctx.fill();
    ctx.fillStyle = 'white';
    ctx.font = '8px sans-serif';
    ctx.textAlign = 'center';
    ctx.textBaseline = 'middle';
    ctx.fillText(ion.type.label, ion.x, ion.y);
  });

  // Bubbles
  if (powerOn && voltage > 1) {
    if (Math.random() < 0.1 * voltage) {
      // Cl2 at Anode (Left)
      bubbles.push({ x: 140 + Math.random() * 25, y: 300, r: 2 + Math.random() * 3, speed: 1 + Math.random(), type: 'cl2' });
    }
    if (Math.random() < 0.15 * voltage) {
      // H2 at Cathode (Right)
      bubbles.push({ x: width - 165 + Math.random() * 25, y: 300, r: 1 + Math.random() * 2, speed: 1.5 + Math.random(), type: 'h2' });
    }
  }

  for (let i = bubbles.length - 1; i >= 0; i--) {
    const b = bubbles[i];
    b.y -= b.speed;
    ctx.beginPath();
    ctx.arc(b.x, b.y, b.r, 0, Math.PI * 2);
    ctx.strokeStyle = b.type === 'cl2' ? 'rgba(163, 230, 53, 0.6)' : 'rgba(255, 255, 255, 0.8)';
    ctx.lineWidth = 1;
    ctx.stroke();
    if (b.y < 100) bubbles.splice(i, 1);
  }

  requestAnimationFrame(animate);
}

init();
</script>
