<script>
  let currentStep = 0;
  const steps = ['P', 'F1', 'F2'];

  function setStep(index) {
    currentStep = index;
    updateUI();
  }

  function nextStep() {
    if (currentStep < 2) {
      currentStep++;
      updateUI();
    }
  }

  function prevStep() {
    if (currentStep > 0) {
      currentStep--;
      updateUI();
    }
  }

  function resetExperiment() {
    currentStep = 0;
    updateUI();
  }

  function updateUI() {
    // Update Stepper
    document.querySelectorAll('.step').forEach((el, i) => {
      el.classList.toggle('active', i === currentStep);
    });

    const viz = document.getElementById('viz-container');
    const phaseText = document.getElementById('current-phase-text');
    const ratioText = document.getElementById('phenotype-ratio');
    const genoStats = document.getElementById('genotype-stats');
    const nextBtn = document.getElementById('next-btn');

    nextBtn.disabled = currentStep === 2;

    if (currentStep === 0) {
      phaseText.textContent = "亲本杂交 (P)";
      ratioText.textContent = "1 : 1 (纯合)";
      genoStats.innerHTML = "YY (黄色纯种) × yy (绿色纯种)";
      viz.innerHTML = `
        <div style="display: flex; align-items: center; gap: 40px;">
          <div style="text-align: center;">
