<script>
  const sentences = [
    {
      tokens: ["机器人", "没有", "过", "马路", "因为", "它", "太", "累", "了"],
      // Head 0: "它" -> "机器人" (指代消解)
      // Head 1: "它" -> "累" (属性关联)
      heads: [
        [0.8, 0.05, 0.02, 0.03, 0.05, 0.01, 0.01, 0.02, 0.01], // Head 0 for "它"
        [0.05, 0.02, 0.03, 0.05, 0.1, 0.05, 0.2, 0.4, 0.1]    // Head 1 for "它"
      ]
    },
    {
      tokens: ["苹果", "公司", "发布", "了", "新款", "手机", "它", "很", "贵"],
      heads: [
        [0.7, 0.1, 0.05, 0.02, 0.03, 0.05, 0.01, 0.02, 0.02], // Head 0 for "它" -> "苹果"
        [0.02, 0.03, 0.05, 0.05, 0.1, 0.2, 0.05, 0.1, 0.4]    // Head 1 for "它" -> "贵"
      ]
    }
  ];

  let state = {
    sentenceIdx: 0,
    wordIdx: 5, // Default "它"
    headIdx: 0
  };

  const tokensTop = document.getElementById('tokens-top');
  const tokensBottom = document.getElementById('tokens-bottom');
  const svg = document.getElementById('attention-svg');
  const heatmap = document.getElementById('heatmap-grid');
  const headSlider = document.getElementById('head-slider');
  const headLabel = document.getElementById('head-label');
  const sentenceSelect = document.getElementById('sentence-select');

  function init() {
    renderTokens();
    renderPosEncoding();
    update();

    headSlider.addEventListener('input', (e) => {
      state.headIdx = parseInt(e.target.value);
      headLabel.textContent = `头 ${state.headIdx + 1}`;
      update();
    });

    sentenceSelect.addEventListener('change', (e) => {
      state.sentenceIdx = parseInt(e.target.value);
      state.wordIdx = state.sentenceIdx === 0 ? 5 : 6; // Reset to "它"
      renderTokens();
      update();
    });
  }

  function renderTokens() {
    const s = sentences[state.sentenceIdx];
    tokensTop.innerHTML = '';
    tokensBottom.innerHTML = '';
    s.tokens.forEach((t, i) => {
      const elTop = document.createElement('div');
      elTop.className = 'token';
      elTop.textContent = t;
      tokensTop.appendChild(elTop);

      const elBot = document.createElement('div');
      elBot.className = 'token';
      elBot.textContent = t;
      elBot.onclick = () => {
        state.wordIdx = i;
        update();
      };
      tokensBottom.appendChild(elBot);
    });
  }

  function update() {
    const s = sentences[state.sentenceIdx];
    const weights = s.heads[state.headIdx];

    // Update token selection
    const bots = tokensBottom.querySelectorAll('.token');
    bots.forEach((el, i) => {
      el.className = i === state.wordIdx ? 'token selected' : 'token';
    });

    // Draw lines
    svg.innerHTML = '';
    const topRects = Array.from(tokensTop.querySelectorAll('.token')).map(el => el.getBoundingClientRect());
    const botRects = Array.from(tokensBottom.querySelectorAll('.token')).map(el => el.getBoundingClientRect());
    const svgRect = svg.getBoundingClientRect();

    const targetBot = botRects[state.wordIdx];
    const xBot = targetBot.left + targetBot.width / 2 - svgRect.left;
    const yBot = targetBot.top - svgRect.top;

    topRects.forEach((top, i) => {
      const xTop = top.left + top.width / 2 - svgRect.left;
      const yTop = top.bottom - svgRect.top;

      // Mock weight calculation: if i is target word, use specific head weights, else random-ish
      let w = (i === state.wordIdx) ? 0.1 : weights[i] || 0.05;
      if (i === state.wordIdx) w = 0.05; // Self-attention to self is usually there but less interesting for demo

      const line = document.createElementNS("http://www.w3.org/2000/svg", "path");
      const cp1y = yBot - 40;
      const cp2y = yTop + 40;
      line.setAttribute("d", `M ${xBot} ${yBot} C ${xBot} ${cp1y}, ${xTop} ${cp2y}, ${xTop} ${yTop}`);
      line.setAttribute("stroke", "var(--accent-amber)");
      line.setAttribute("stroke-width", Math.max(0.5, w * 15));
      line.setAttribute("fill", "none");
      line.setAttribute("opacity", Math.max(0.1, w * 1.5));
      svg.appendChild(line);
    });

    // Update Heatmap
    heatmap.innerHTML = '';
    for (let i = 0; i < 100; i++) {
      const cell = document.createElement('div');
      cell.className = 'heat-cell';
      const row = Math.floor(i / 10);
      const col = i % 10;
      let val = 0.1;
      if (row === state.wordIdx) val = weights[col] || 0.1;
      cell.style.background = `rgba(239, 159, 39, ${val * 2})`;
      heatmap.appendChild(cell);
    }
  }

  function renderPosEncoding() {
    const canvas = document.getElementById('pos-canvas');
    const ctx = canvas.getContext('2d');
    ctx.clearRect(0, 0, 200, 100);

    // Draw Sine
    ctx.beginPath();
    ctx.strokeStyle = '#378ADD';
    ctx.lineWidth = 2;
    for(let x=0; x<200; x++) {
      const y = 50 + Math.sin(x/10) * 30;
      if(x===0) ctx.moveTo(x, y); else ctx.lineTo(x, y);
    }
    ctx.stroke();

    // Draw Cosine
    ctx.beginPath();
    ctx.strokeStyle = '#E24B4A';
    ctx.setLineDash([4, 2]);
    for(let x=0; x<200; x++) {
      const y = 50 + Math.cos(x/15) * 25;
      if(x===0) ctx.moveTo(x, y); else ctx.lineTo(x, y);
    }
    ctx.stroke();
  }

  window.addEventListener('resize', update);
  init();
</script>
