<script>
  const words = ["Transformer", "改变了", "语言", "模型"];
  const stages = ['embedding', 'positional', 'attention'];
  let currentStage = 'attention';
  let currentHead = 1;
  let activeWordIdx = 1; // "改变了"

  // Mock attention weights for 4 heads
  const attentionData = {
    1: [ // Head 1: Focus on neighbors
      [0.7, 0.2, 0.05, 0.05],
      [0.2, 0.6, 0.2, 0.0],
      [0.0, 0.2, 0.6, 0.2],
      [0.05, 0.05, 0.2, 0.7]
    ],
    2: [ // Head 2: Focus on subject (Transformer)
      [0.9, 0.03, 0.03, 0.04],
      [0.8, 0.1, 0.05, 0.05],
      [0.7, 0.1, 0.1, 0.1],
      [0.6, 0.1, 0.1, 0.2]
    ],
    3: [ // Head 3: Focus on object (模型)
      [0.1, 0.1, 0.2, 0.6],
      [0.05, 0.1, 0.25, 0.6],
      [0.05, 0.05, 0.1, 0.8],
      [0.05, 0.05, 0.1, 0.8]
    ],
    4: [ // Head 4: Global/Uniform
      [0.25, 0.25, 0.25, 0.25],
      [0.25, 0.25, 0.25, 0.25],
      [0.25, 0.25, 0.25, 0.25],
      [0.25, 0.25, 0.25, 0.25]
    ]
  };

  const headColors = ['#378ADD', '#1D9E75', '#D85A30', '#7F77DD'];

  function init() {
    const queryChips = document.getElementById('query-chips');
    const topRow = document.getElementById('top-row');
    const bottomRow = document.getElementById('bottom-row');

    words.forEach((word, i) => {
      // Query Chips
      const chip = document.createElement('button');
      chip.textContent = word;
      chip.style.fontSize = '12px';
      chip.style.padding = '2px 8px';
      chip.onclick = () => { activeWordIdx = i; update(); };
      chip.id = `chip-${i}`;
      queryChips.appendChild(chip);

      // Top Nodes
      const tNode = document.createElement('div');
      tNode.className = 'word-node';
      tNode.textContent = word;
      tNode.id = `top-${i}`;
      topRow.appendChild(tNode);

      // Bottom Nodes
      const bNode = document.createElement('div');
      bNode.className = 'word-node';
      bNode.textContent = word;
      bNode.id = `bottom-${i}`;
      bottomRow.appendChild(bNode);
    });

    document.getElementById('stage-select').onchange = (e) => {
      currentStage = e.target.value;
      update();
    };

    document.getElementById('head-slider').oninput = (e) => {
      currentHead = parseInt(e.target.value);
      update();
    };

    update();
    window.addEventListener('resize', update);
  }

  function update() {
    // Update UI States
    words.forEach((_, i) => {
      document.getElementById(`chip-${i}`).className = (i === activeWordIdx) ? 'active' : '';
      document.getElementById(`top-${i}`).className = (i === activeWordIdx && currentStage === 'attention') ? 'word-node active' : 'word-node';
    });

    document.getElementById('dot-1').className = currentStage === 'embedding' ? 'stage-dot active' : 'stage-dot';
    document.getElementById('dot-2').className = currentStage === 'positional' ? 'stage-dot active' : 'stage-dot';
    document.getElementById('dot-3').className = currentStage === 'attention' ? 'stage-dot active' : 'stage-dot';

    const svg = document.getElementById('attn-svg');
    svg.innerHTML = '';
    const heatmap = document.getElementById('heatmap');
    heatmap.innerHTML = '';

    if (currentStage === 'attention') {
      drawAttention();
    } else if (currentStage === 'positional') {
      drawPositional();
    } else {
      drawEmbedding();
    }
  }

  function drawAttention() {
    const svg = document.getElementById('attn-svg');
    const weights = attentionData[currentHead][activeWordIdx];
    const color = headColors[currentHead - 1];

    words.forEach((_, i) => {
      const topEl = document.getElementById(`top-${activeWordIdx}`);
      const botEl = document.getElementById(`bottom-${i}`);

      const tRect = topEl.getBoundingClientRect();
      const bRect = botEl.getBoundingClientRect();
      const containerRect = document.getElementById('viz-area').getBoundingClientRect();

      const x1 = tRect.left + tRect.width / 2 - containerRect.left;
      const y1 = tRect.bottom - containerRect.top;
      const x2 = bRect.left + bRect.width / 2 - containerRect.left;
      const y2 = bRect.top - containerRect.top;

      const line = document.createElementNS("http://www.w3.org/2000/svg", "line");
      line.setAttribute("x1", x1);
      line.setAttribute("y1", y1);
      line.setAttribute("x2", x2);
      line.setAttribute("y2", y2);
      line.setAttribute("stroke", color);
      line.setAttribute("stroke-width", weights[i] * 8 + 0.5);
      line.setAttribute("stroke-opacity", weights[i] * 0.8 + 0.1);
      svg.appendChild(line);
    });

    // Heatmap for attention
    const label = document.createElement('div');
    label.style.fontSize = '12px';
    label.style.color = 'var(--color-text-secondary)';
    label.textContent = `注意力分布 (Head ${currentHead})`;
    document.getElementById('heatmap').appendChild(label);

    const row = document.createElement('div');
    row.className = 'heatmap-row';
    weights.forEach(w => {
      const cell = document.createElement('div');
      cell.className = 'heatmap-cell';
      cell.style.background = color;
      cell.style.opacity = w;
      row.appendChild(cell);
    });
    document.getElementById('heatmap').appendChild(row);
  }

  function drawPositional() {
    const heatmap = document.getElementById('heatmap');
    const label = document.createElement('div');
    label.style.fontSize = '12px';
    label.style.color = 'var(--color-text-secondary)';
    label.textContent = "位置编码矩阵 (Sin/Cos 叠加)";
    heatmap.appendChild(label);

    for (let i = 0; i < 4; i++) {
      const row = document.createElement('div');
      row.className = 'heatmap-row';
      for (let j = 0; j < 20; j++) {
        const cell = document.createElement('div');
        cell.className = 'heatmap-cell';
        const val = Math.sin(i * 0.5 + j * 0.2);
        cell.style.background = '#AFA9EC';
        cell.style.opacity = (val + 1) / 2;
        row.appendChild(cell);
      }
      heatmap.appendChild(row);
    }
  }

  function drawEmbedding() {
    const heatmap = document.getElementById('heatmap');
    const label = document.createElement('div');
    label.style.fontSize = '12px';
    label.style.color = 'var(--color-text-secondary)';
    label.textContent = "词嵌入向量 (语义空间映射)";
    heatmap.appendChild(label);

    words.forEach((_, i) => {
      const row = document.createElement('div');
      row.className = 'heatmap-row';
      for (let j = 0; j < 20; j++) {
        const cell = document.createElement('div');
        cell.className = 'heatmap-cell';
        cell.style.background = '#9FE1CB';
        cell.style.opacity = Math.random() * 0.8 + 0.2;
        row.appendChild(cell);
      }
      heatmap.appendChild(row);
    });
  }

  init();
</script>
