  <div class="main-layout">
    <!-- 模拟画布 -->
    <div class="sim-box">
      <canvas id="electrolysisCanvas"></canvas>
    </div>

    <!-- 信息面板 -->
    <div class="info-panel">
      <div class="card">
        <h3>反应方程式</h3>
        <div class="equation">
          <span class="badge" style="background:rgba(102,187,106,0.2); color:var(--cl-color)">阳极 (+) 氧化反应:</span><br>
          2Cl⁻ → Cl₂↑ + 2e⁻
        </div>
        <div class="equation">
          <span class="badge" style="background:rgba(236,64,122,0.2); color:var(--oh-color)">阴极 (-) 还原反应:</span><br>
          2H₂O + 2e⁻ → H₂↑ + 2OH⁻
        </div>
