        <div class="legend">
          <div class="legend-item"><div class="dot" style="background:var(--na-color)"></div> Na⁺ (钠离子)</div>
          <div class="legend-item"><div class="dot" style="background:var(--cl-color)"></div> Cl⁻ (氯离子)</div>
          <div class="legend-item"><div class="dot" style="background:var(--oh-color)"></div> OH⁻ (氢氧根)</div>
          <div class="legend-item"><div class="dot" style="background:var(--h-color)"></div> H₂O (水分子)</div>
        </div>
      </div>
    </div>
