  <!-- 控制栏 -->
  <div class="controls">
    <button id="toggleBtn" class="btn btn-primary">开始电解</button>
    <div class="slider-group">
      <label style="font-size: 14px;">电压强度</label>
      <input type="range" id="voltageSlider" min="1" max="10" value="5">
    </div>
  </div>
