<script>
  const canvas = document.getElementById('electrolysisCanvas');
  const ctx = canvas.getContext('2d');
  const toggleBtn = document.getElementById('toggleBtn');
  const voltageSlider = document.getElementById('voltageSlider');

  let running = false;
  let width, height;
  let ions = [];
  let bubbles = [];
  let phClouds = [];
  let voltage = 5;

  class Ion {
    constructor(type) {
      this.type = type;
      this.reset();
    }
    reset() {
      this.x = Math.random() * (width - 100) + 50;
      this.y = Math.random() * (height - 150) + 100;
      this.vx = (Math.random() - 0.5) * 1;
      this.vy = (Math.random() - 0.5) * 1;
      this.radius = 6;
    }
    update() {
      if (running) {
        // 阳极在左 (x=100), 阴极在右 (x=width-100)
        if (this.type === 'Cl-') {
          this.vx += (100 - this.x) * 0.0005 * voltage;
        } else if (this.type === 'Na+') {
          this.vx += (width - 100 - this.x) * 0.0005 * voltage;
        } else if (this.type === 'OH-') {
          this.vx += (width - 100 - this.x) * 0.0002 * voltage;
        }
      }

      this.x += this.vx;
      this.y += this.vy;
      this.vx *= 0.98;
      this.vy *= 0.98;
      this.vx += (Math.random() - 0.5) * 0.2;
      this.vy += (Math.random() - 0.5) * 0.2;

      // 边界检查
      if (this.x < 40 || this.x > width - 40) this.vx *= -1;
      if (this.y < 100 || this.y > height - 40) this.vy *= -1;

      // 反应逻辑
      if (running) {
        if (this.type === 'Cl-' && this.x < 115 && Math.abs(this.y - height/2) < 100) {
          if (Math.random() < 0.1 * voltage) {
            createBubble(this.x, this.y, 'Cl2');
            this.reset();
          }
        }
        if (Math.random() < 0.005 * voltage) {
           // 模拟阴极水还原产生H2和OH-
           if (Math.random() < 0.1) {
             createBubble(width - 110, height/2 + (Math.random()-0.5)*180, 'H2');
             if (ions.filter(i => i.type === 'OH-').length < 30) {
                ions.push(new Ion('OH-'));
             }
           }
        }
      }
    }
    draw() {
      ctx.beginPath();
      ctx.arc(this.x, this.y, this.radius, 0, Math.PI * 2);
      if (this.type === 'Na+') ctx.fillStyle = '#42a5f5';
      else if (this.type === 'Cl-') ctx.fillStyle = '#66bb6a';
      else if (this.type === 'OH-') ctx.fillStyle = '#ec407a';
      ctx.fill();
      ctx.fillStyle = 'white';
      ctx.font = 'bold 8px sans-serif';
      ctx.textAlign = 'center';
      ctx.textBaseline = 'middle';
      ctx.fillText(this.type, this.x, this.y);
    }
  }

  class Bubble {
    constructor(x, y, type) {
      this.x = x;
      this.y = y;
      this.type = type;
      this.r = 2 + Math.random() * 4;
      this.vy = - (1 + Math.random() * 2);
      this.vx = (Math.random() - 0.5) * 0.5;
      this.life = 1.0;
    }
    update() {
      this.y += this.vy;
      this.x += this.vx;
      this.life -= 0.01;
    }
    draw() {
      ctx.beginPath();
      ctx.arc(this.x, this.y, this.r, 0, Math.PI * 2);
      ctx.strokeStyle = this.type === 'Cl2' ? 'rgba(102,187,106,0.6)' : 'rgba(255,255,255,0.8)';
      ctx.lineWidth = 1;
      ctx.stroke();
      if (this.type === 'Cl2') {
        ctx.fillStyle = 'rgba(102,187,106,0.2)';
        ctx.fill();
      }
    }
  }

  function createBubble(x, y, type) {
    bubbles.push(new Bubble(x, y, type));
  }

  function init() {
    width = canvas.parentElement.clientWidth;
    height = canvas.parentElement.clientHeight;
    canvas.width = width;
    canvas.height = height;

    ions = [];
    for (let i = 0; i < 15; i++) ions.push(new Ion('Na+'));
    for (let i = 0; i < 15; i++) ions.push(new Ion('Cl-'));

    animate();
  }

  function drawCell() {
    // 烧杯
    ctx.strokeStyle = '#999';
    ctx.lineWidth = 3;
    ctx.beginPath();
    ctx.moveTo(40, 80);
    ctx.lineTo(40, height - 30);
    ctx.lineTo(width - 40, height - 30);
    ctx.lineTo(width - 40, 80);
    ctx.stroke();

    // 溶液
    ctx.fillStyle = 'rgba(0, 150, 255, 0.05)';
    ctx.fillRect(40, 100, width - 80, height - 130);

    // 阴极区域的酚酞变色效果 (OH- 积累)
    if (running) {
      let gradient = ctx.createRadialGradient(width - 100, height/2, 20, width - 100, height/2, 150);
      gradient.addColorStop(0, 'rgba(236, 64, 122, 0.15)');
      gradient.addColorStop(1, 'rgba(236, 64, 122, 0)');
      ctx.fillStyle = gradient;
      ctx.fillRect(width/2, 100, width/2 - 40, height - 130);
    }

    // 电极
    ctx.fillStyle = '#333';
    // 阳极 (+)
    ctx.fillRect(90, 60, 20, height - 120);
    // 阴极 (-)
    ctx.fillRect(width - 110, 60, 20, height - 120);

    // 标签
    ctx.fillStyle = varColor('--color-text-primary');
    ctx.font = '12px sans-serif';
    ctx.textAlign = 'center';
    ctx.fillText('阳极 (+)', 100, 50);
    ctx.fillText('阴极 (-)', width - 100, 50);
  }

  function varColor(name) {
    return getComputedStyle(document.documentElement).getPropertyValue(name).trim();
  }

  function animate() {
    ctx.clearRect(0, 0, width, height);

    drawCell();

    ions.forEach(ion => {
      ion.update();
      ion.draw();
    });

    bubbles = bubbles.filter(b => b.y > 80 && b.life > 0);
    bubbles.forEach(b => {
      b.update();
      b.draw();
    });

    requestAnimationFrame(animate);
  }

  toggleBtn.addEventListener('click', () => {
    running = !running;
    toggleBtn.textContent = running ? '停止电解' : '开始电解';
    toggleBtn.className = running ? 'btn btn-stop' : 'btn btn-primary';
  });

  voltageSlider.addEventListener('input', (e) => {
    voltage = parseInt(e.target.value);
  });

  window.addEventListener('resize', init);
  init();
</script>
