<div class="container">
    <div class="graph-container" id="graph">
        <svg id="svg-root" viewBox="0 0 480 380">
            <defs>
                <marker id="arrowhead" markerWidth="10" markerHeight="7" refX="20" refY="3.5" orient="auto">
                    <polygon points="0 0, 10 3.5, 0 7" fill="#cbd5e1" />
                </marker>
            </defs>
            <g id="edges-layer"></g>
            <g id="nodes-layer"></g>
        </svg>
    </div>

    <div class="sidebar">
        <div class="info-panel">
            <div class="panel-title">最短路径估计 (Dist)</div>
            <table class="dist-table">
                <thead>
                    <tr>
                        <th>节点</th>
                        <th>距离</th>
                        <th>前驱</th>
                        <th>状态</th>
                    </tr>
                </thead>
                <tbody id="table-body">
                    <!-- Rows injected by JS -->
                </tbody>
            </table>
            <div class="panel-title" style="margin-top: 15px;">当前步骤</div>
            <div class="explanation" id="step-desc">
                准备开始算法。我们将计算从节点 A 到所有其他节点的最短路径。
            </div>
        </div>
    </div>

    <div class="controls">
        <button id="btn-reset">重置</button>
        <button id="btn-prev">上一步</button>
        <button id="btn-next" class="primary">下一步</button>
        <button id="btn-auto">自动播放</button>
    </div>
</div>

<script>
const nodes = [
    { id: 'A', x: 60,  y: 190 },
    { id: 'B', x: 160, y: 80  },
    { id: 'C', x: 160, y: 300 },
    { id: 'D', x: 320, y: 80  },
    { id: 'E', x: 320, y: 300 },
    { id: 'F', x: 420, y: 190 }
];

const edges = [
    { from: 'A', to: 'B', w: 4 },
    { from: 'A', to: 'C', w: 2 },
    { from: 'B', to: 'C', w: 1 },
    { from: 'B', to: 'D', w: 5 },
    { from: 'C', to: 'D', w: 8 },
    { from: 'C', to: 'E', w: 10 },
    { from: 'D', to: 'E', w: 2 },
    { from: 'D', to: 'F', w: 6 },
    { from: 'E', to: 'F', w: 3 }
];

let currentStepIdx = 0;
let steps = [];
let autoPlayTimer = null;

function initAlgorithm() {
    steps = [];

    // Initial state
    let state = {
        dist: { A: 0, B: Infinity, C: Infinity, D: Infinity, E: Infinity, F: Infinity },
        parent: { A: null, B: null, C: null, D: null, E: null, F: null },
        visited: [],
        unvisited: ['A', 'B', 'C', 'D', 'E', 'F'],
        currentNode: null,
        activeEdge: null,
        desc: "初始化：起点 A 距离设为 0，其余设为 ∞。"
    };
    steps.push(JSON.parse(JSON.stringify(state)));

    let unvisited = ['A', 'B', 'C', 'D', 'E', 'F'];
    let dist = { A: 0, B: Infinity, C: Infinity, D: Infinity, E: Infinity, F: Infinity };
    let parent = { A: null, B: null, C: null, D: null, E: null, F: null };
    let visited = [];

    while (unvisited.length > 0) {
        // Step: Pick minimum
        unvisited.sort((a, b) => dist[a] - dist[b]);
        let u = unvisited.shift();

        if (dist[u] === Infinity) break;

        state = { 
            dist: {...dist}, parent: {...parent}, visited: [...visited], unvisited: [...unvisited],
            currentNode: u, activeEdge: null, 
            desc: `从待选节点中选择距离最小的节点 <b>${u}</b> (距离: ${dist[u]})。` 
        };
        steps.push(JSON.parse(JSON.stringify(state)));

        // Step: Relax neighbors
        let neighbors = edges.filter(e => e.from === u || e.to === u);
        for (let edge of neighbors) {
            let v = (edge.from === u) ? edge.to : edge.from;
            if (visited.includes(v)) continue;

            let weight = edge.w;
            let newDist = dist[u] + weight;

            let relaxed = false;
            let desc = `检查邻居节点 <b>${v}</b>。当前路径长度: ${dist[u]} + ${weight} = ${newDist}。`;

            if (newDist < dist[v]) {
                dist[v] = newDist;
                parent[v] = u;
                relaxed = true;
                desc += ` 发现更短路径！更新 <b>${v}</b> 的距离为 ${newDist}。`;
            } else {
                desc += ` 不短于现有距离 ${dist[v] === Infinity ? '∞' : dist[v]}，不更新。`;
            }

            state = { 
                dist: {...dist}, parent: {...parent}, visited: [...visited], unvisited: [...unvisited],
                currentNode: u, activeEdge: {from: u, to: v},
                desc: desc
            };
            steps.push(JSON.parse(JSON.stringify(state)));
        }

        visited.push(u);
        state = { 
            dist: {...dist}, parent: {...parent}, visited: [...visited], unvisited: [...unvisited],
            currentNode: u, activeEdge: null,
            desc: `节点 <b>${u}</b> 的所有邻居已检查完毕，标记为“已确定”。`
        };
        steps.push(JSON.parse(JSON.stringify(state)));
    }

    steps.push({
        ...state,
        currentNode: null,
        activeEdge: null,
        desc: "算法完成！已找到从起点 A 到所有可达节点的最短路径。"
    });
}

function render() {
    const state = steps[currentStepIdx];
    const nodesLayer = document.getElementById('nodes-layer');
    const edgesLayer = document.getElementById('edges-layer');
    const tableBody = document.getElementById('table-body');
    const stepDesc = document.getElementById('step-desc');

    // Render Edges
    edgesLayer.innerHTML = '';
    edges.forEach(edge => {
        const fromNode = nodes.find(n => n.id === edge.from);
        const toNode = nodes.find(n => n.id === edge.to);

        const line = document.createElementNS("http://www.w3.org/2000/svg", "line");
        line.setAttribute("x1", fromNode.x);
        line.setAttribute("y1", fromNode.y);
        line.setAttribute("x2", toNode.x);
        line.setAttribute("y2", toNode.y);
        line.setAttribute("class", "edge");

        // Highlight active edge
        if (state.activeEdge && 
           ((state.activeEdge.from === edge.from && state.activeEdge.to === edge.to) ||
            (state.activeEdge.from === edge.to && state.activeEdge.to === edge.from))) {
            line.classList.add('active');
        }

        // Highlight shortest path tree edges
        if (state.parent[edge.to] === edge.from || state.parent[edge.from] === edge.to) {
            // Only show as shortest if the child node is visited or being processed
            const child = state.parent[edge.to] === edge.from ? edge.to : edge.from;
            if (state.visited.includes(child) || state.currentNode === child) {
                line.classList.add('shortest');
            }
        }

        edgesLayer.appendChild(line);

        // Weight labels
        const text = document.createElementNS("http://www.w3.org/2000/svg", "text");
        text.setAttribute("x", (fromNode.x + toNode.x) / 2);
        text.setAttribute("y", (fromNode.y + toNode.y) / 2 - 5);
        text.setAttribute("class", "edge-weight");
        text.setAttribute("text-anchor", "middle");
        text.textContent = edge.w;
        edgesLayer.appendChild(text);
    });

    // Render Nodes
    nodesLayer.innerHTML = '';
    nodes.forEach(node => {
        const g = document.createElementNS("http://www.w3.org/2000/svg", "g");

        const circle = document.createElementNS("http://www.w3.org/2000/svg", "circle");
        circle.setAttribute("cx", node.x);
        circle.setAttribute("cy", node.y);
        circle.setAttribute("r", 18);
        circle.setAttribute("class", "node-circle");

        if (state.visited.includes(node.id)) circle.classList.add('visited');
        if (state.currentNode === node.id) circle.classList.add('current');

        const text = document.createElementNS("http://www.w3.org/2000/svg", "text");
        text.setAttribute("x", node.x);
        text.setAttribute("y", node.y + 5);
        text.setAttribute("text-anchor", "middle");
        text.setAttribute("class", "node-label");
        text.textContent = node.id;

        g.appendChild(circle);
        g.appendChild(text);
        nodesLayer.appendChild(g);
    });

    // Render Table
    tableBody.innerHTML = '';
    nodes.forEach(node => {
        const tr = document.createElement('tr');
        if (state.currentNode === node.id) tr.classList.add('highlight');
        if (state.visited.includes(node.id)) tr.classList.add('fixed');

        const d = state.dist[node.id];
        const p = state.parent[node.id] || '-';
        const s = state.visited.includes(node.id) ? '已确定' : (state.currentNode === node.id ? '处理中' : '未访问');

        tr.innerHTML = `
            <td>${node.id}</td>
            <td>${d === Infinity ? '∞' : d}</td>
            <td>${p}</td>
            <td><span class="badge ${s === '已确定' ? 'badge-blue' : ''}">${s}</span></td>
        `;
        tableBody.appendChild(tr);
    });

    stepDesc.innerHTML = state.desc;

    // Button states
    document.getElementById('btn-prev').disabled = currentStepIdx === 0;
    document.getElementById('btn-next').disabled = currentStepIdx === steps.length - 1;
}

// Event Listeners
document.getElementById('btn-next').addEventListener('click', () => {
    if (currentStepIdx < steps.length - 1) {
        currentStepIdx++;
        render();
    }
});

document.getElementById('btn-prev').addEventListener('click', () => {
    if (currentStepIdx > 0) {
        currentStepIdx--;
        render();
    }
});

document.getElementById('btn-reset').addEventListener('click', () => {
    stopAutoPlay();
    currentStepIdx = 0;
    render();
});

document.getElementById('btn-auto').addEventListener('click', () => {
    if (autoPlayTimer) {
        stopAutoPlay();
    } else {
        startAutoPlay();
    }
});

function startAutoPlay() {
    if (currentStepIdx >= steps.length - 1) currentStepIdx = 0;
    document.getElementById('btn-auto').textContent = "停止播放";
    autoPlayTimer = setInterval(() => {
        if (currentStepIdx < steps.length - 1) {
            currentStepIdx++;
            render();
        } else {
            stopAutoPlay();
        }
    }, 800);
}

function stopAutoPlay() {
    clearInterval(autoPlayTimer);
    autoPlayTimer = null;
    document.getElementById('btn-auto').textContent = "自动播放";
}

