<script>
const nodes = [
    { id: 'A', x: 60,  y: 170 },
    { id: 'B', x: 170, y: 70  },
    { id: 'C', x: 170, y: 270 },
    { id: 'D', x: 310, y: 70  },
    { id: 'E', x: 310, y: 270 },
    { id: 'F', x: 420, y: 170 }
];

const edges = [
    { from: 'A', to: 'B', w: 4 },
    { from: 'A', to: 'C', w: 2 },
    { from: 'B', to: 'C', w: 1 },
    { from: 'B', to: 'D', w: 5 },
    { from: 'C', to: 'D', w: 8 },
    { from: 'C', to: 'E', w: 10 },
    { from: 'D', to: 'E', w: 2 },
    { from: 'D', to: 'F', w: 6 },
    { from: 'E', to: 'F', w: 3 }
];

let currentStepIdx = 0;
let steps = [];
let autoPlayTimer = null;

function generateSteps() {
    steps = [];
    let dist = { A: 0, B: Infinity, C: Infinity, D: Infinity, E: Infinity, F: Infinity };
    let parent = { A: null, B: null, C: null, D: null, E: null, F: null };
    let visited = [];
    let unvisited = ['A', 'B', 'C', 'D', 'E', 'F'];

    // Initial state
    steps.push({
        dist: {...dist}, parent: {...parent}, visited: [],
        currentNode: null, activeEdge: null,
        desc: "算法开始：将起点 A 的距离设为 0，其余节点设为无穷大 (∞)。"
    });

    while (unvisited.length > 0) {
        // Find min dist in unvisited
        unvisited.sort((a, b) => dist[a] - dist[b]);
        let u = unvisited[0];

        if (dist[u] === Infinity) break;
        unvisited.shift();

        steps.push({
            dist: {...dist}, parent: {...parent}, visited: [...visited],
            currentNode: u, activeEdge: null,
            desc: `在未确定的节点中，选择距离最小的节点 <b>${u}</b> (距离: ${dist[u]})。`
        });

        // Relax neighbors
        let neighbors = edges.filter(e => e.from === u || e.to === u);
        for (let edge of neighbors) {
            let v = (edge.from === u) ? edge.to : edge.from;
            if (visited.includes(v)) continue;

            let newDist = dist[u] + edge.w;
            let relaxed = false;
            let stepDesc = `检查从 ${u} 到 ${v} 的边 (权重: ${edge.w})。`;

            if (newDist < dist[v]) {
                dist[v] = newDist;
                parent[v] = u;
                relaxed = true;
                stepDesc += ` 发现更短路径！更新 ${v} 的距离为 ${newDist}。`;
            } else {
                stepDesc += ` 路径长度 ${newDist} 不优于现有距离 ${dist[v] === Infinity ? '∞' : dist[v]}。`;
            }

            steps.push({
                dist: {...dist}, parent: {...parent}, visited: [...visited],
                currentNode: u, activeEdge: {from: u, to: v},
                desc: stepDesc
            });
        }

        visited.push(u);
        steps.push({
            dist: {...dist}, parent: {...parent}, visited: [...visited],
            currentNode: u, activeEdge: null,
            desc: `节点 <b>${u}</b> 的所有邻居已检查完毕，标记其最短路径已确定。`
        });
    }

    steps.push({
        dist: {...dist}, parent: {...parent}, visited: [...visited],
        currentNode: null, activeEdge: null,
        desc: "算法执行完毕。已找到从 A 出发到所有可达节点的最短路径。"
    });
}

function render() {
    const state = steps[currentStepIdx];
    const edgesLayer = document.getElementById('edges-layer');
    const nodesLayer = document.getElementById('nodes-layer');
    const tableBody = document.getElementById('table-body');
    const stepDesc = document.getElementById('step-desc');

    // Edges
    edgesLayer.innerHTML = '';
    edges.forEach(edge => {
        const n1 = nodes.find(n => n.id === edge.from);
        const n2 = nodes.find(n => n.id === edge.to);
        const line = document.createElementNS("http://www.w3.org/2000/svg", "line");
        line.setAttribute("x1", n1.x); line.setAttribute("y1", n1.y);
        line.setAttribute("x2", n2.x); line.setAttribute("y2", n2.y);
        line.setAttribute("class", "edge");

        if (state.activeEdge && ((state.activeEdge.from === edge.from && state.activeEdge.to === edge.to) || (state.activeEdge.from === edge.to && state.activeEdge.to === edge.from))) {
            line.classList.add('active');
        }

        // Shortest path tree highlight
        if (state.parent[edge.to] === edge.from || state.parent[edge.from] === edge.to) {
            const child = state.parent[edge.to] === edge.from ? edge.to : edge.from;
            if (state.visited.includes(child) || state.currentNode === child) {
                line.classList.add('shortest');
            }
        }
        edgesLayer.appendChild(line);

        const text = document.createElementNS("http://www.w3.org/2000/svg", "text");
        text.setAttribute("x", (n1.x + n2.x) / 2);
        text.setAttribute("y", (n1.y + n2.y) / 2 - 6);
        text.setAttribute("class", "edge-weight");
        text.setAttribute("text-anchor", "middle");
        text.textContent = edge.w;
        edgesLayer.appendChild(text);
    });

    // Nodes
    nodesLayer.innerHTML = '';
    nodes.forEach(node => {
        const g = document.createElementNS("http://www.w3.org/2000/svg", "g");
        const circle = document.createElementNS("http://www.w3.org/2000/svg", "circle");
        circle.setAttribute("cx", node.x); circle.setAttribute("cy", node.y);
        circle.setAttribute("r", 18);
        circle.setAttribute("class", "node-circle");
        if (state.visited.includes(node.id)) circle.classList.add('visited');
        if (state.currentNode === node.id) circle.classList.add('current');

        const text = document.createElementNS("http://www.w3.org/2000/svg", "text");
        text.setAttribute("x", node.x); text.setAttribute("y", node.y + 5);
        text.setAttribute("text-anchor", "middle");
        text.setAttribute("class", "node-label");
        text.setAttribute("fill", "currentColor");
        text.textContent = node.id;

        g.appendChild(circle);
        g.appendChild(text);
        nodesLayer.appendChild(g);
    });

    // Table
    tableBody.innerHTML = '';
    nodes.forEach(node => {
        const tr = document.createElement('tr');
        if (state.currentNode === node.id) tr.classList.add('row-highlight');
        if (state.visited.includes(node.id)) tr.classList.add('row-fixed');

        const d = state.dist[node.id];
        tr.innerHTML = `
            <td>${node.id}</td>
            <td>${d === Infinity ? '∞' : d}</td>
            <td>${state.parent[node.id] || '-'}</td>
        `;
        tableBody.appendChild(tr);
    });

    stepDesc.innerHTML = state.desc;
    document.getElementById('btn-prev').disabled = currentStepIdx === 0;
    document.getElementById('btn-next').disabled = currentStepIdx === steps.length - 1;
}

document.getElementById('btn-next').onclick = () => { currentStepIdx++; render(); };
document.getElementById('btn-prev').onclick = () => { currentStepIdx--; render(); };
document.getElementById('btn-reset').onclick = () => { 
    stopAuto();
    currentStepIdx = 0; 
    render(); 
};
document.getElementById('btn-auto').onclick = () => {
    if (autoPlayTimer) stopAuto();
    else startAuto();
};

function startAuto() {
    if (currentStepIdx >= steps.length - 1) currentStepIdx = 0;
    document.getElementById('btn-auto').textContent = "停止";
    autoPlayTimer = setInterval(() => {
        if (currentStepIdx < steps.length - 1) {
            currentStepIdx++;
            render();
        } else stopAuto();
    }, 1000);
}

function stopAuto() {
    clearInterval(autoPlayTimer);
    autoPlayTimer = null;
    document.getElementById('btn-auto').textContent = "自动播放";
}

generateSteps();
render();
</script>
