    const ctx = document.getElementById('radarChart').getContext('2d');
    radarChart = new Chart(ctx, {
      type: 'radar',
      data: {
        labels: ['效率', '公平', '秩序', '参与', '响应'],
        datasets: [{
          label: '价值权重',
          data: phases[0].radar,
          backgroundColor: 'rgba(55, 138, 221, 0.2)',
          borderColor: 'rgba(55, 138, 221, 0.8)',
          borderWidth: 2,
          pointRadius: 3
        }]
      },
      options: {
        scales: {
          r: {
            min: 0, max: 100,
            ticks: { display: false },
            grid: { color: 'rgba(0,0,0,0.05)' }
          }
        },
        plugins: { legend: { display: false } }
      }
    });
  }

  function updateSVG() {
    const phase = phases[currentPhase];
    const nodesLayer = document.getElementById('nodes-layer');
    const linksLayer = document.getElementById('links-layer');
    const flowPath = document.getElementById('logic-flow');

    // Clear and redraw links
    linksLayer.innerHTML = '';
    phase.links.forEach(link => {
      const n1 = phase.nodes[link[0]];
      const n2 = phase.nodes[link[1]];
      const line = document.createElementNS("http://www.w3.org/2000/svg", "line");
      line.setAttribute('x1', n1.x); line.setAttribute('y1', n1.y);
      line.setAttribute('x2', n2.x); line.setAttribute('y2', n2.y);
      line.setAttribute('class', 'link');
      linksLayer.appendChild(line);
    });

    // Clear and redraw nodes
    nodesLayer.innerHTML = '';
    phase.nodes.forEach((node, i) => {
      const circle = document.createElementNS("http://www.w3.org/2000/svg", "circle");
      circle.setAttribute('cx', node.x);
      circle.setAttribute('cy', node.y);
      circle.setAttribute('r', node.r);
      circle.setAttribute('class', `node ${node.c}`);
      nodesLayer.appendChild(circle);
    });

    flowPath.setAttribute('d', phase.flow);
    flowPath.style.opacity = showOverlay ? '1' : '0';
  }

  function setPhase(index) {
    currentPhase = index;

    // Update Timeline UI
    document.querySelectorAll('.timeline-step').forEach((el, i) => {
      el.classList.toggle('active', i === index);
    });

    // Update Info Card
    const p = phases[index];
    document.getElementById('phase-title').textContent = p.title;
    document.getElementById('phase-desc').textContent = p.desc;
    document.getElementById('core-view').textContent = p.core;
    document.getElementById('figures').textContent = p.figures;
    document.getElementById('logic').textContent = p.logic;
    document.getElementById('citizen').textContent = p.citizen;

    // Update Radar
    radarChart.data.datasets[0].data = p.radar;
    const colors = ['#378ADD', '#EF9F27', '#1D9E75', '#7F77DD'];
    radarChart.data.datasets[0].borderColor = colors[index];
    radarChart.data.datasets[0].backgroundColor = colors[index] + '33';
    radarChart.update();

    updateSVG();
  }

  function toggleOverlay() {
    showOverlay = !showOverlay;
    document.getElementById('overlayToggle').classList.toggle('active', showOverlay);
    document.getElementById('logic-flow').style.opacity = showOverlay ? '1' : '0';
  }

  // Initialize
  window.onload = () => {
    initRadar();
    updateSVG();
  };
</script>
