<script>
  const tokens = ["The", "robot", "processed", "the", "data"];
  const steps = [
    { name: "输入词嵌入", desc: "将单词转换为高维向量表示。" },
    { name: "生成 QKV", desc: "通过线性变换生成查询 (Query)、键 (Key) 和值 (Value) 向量。" },
    { name: "计算权重", desc: "计算 Query 与所有 Key 的相似度，并进行 Softmax 归一化。" },
    { name: "加权求和", desc: "根据权重对 Value 向量进行加权，提取上下文信息。" },
    { name: "输出表示", desc: "得到包含上下文信息的最终词向量表示。" }
  ];

  // 模拟不同头的注意力权重
  const attentionMaps = [
    // Head 1: 语法 (robot -> processed, processed -> data)
    [
      [0.8, 0.1, 0.05, 0.02, 0.03],
      [0.1, 0.7, 0.15, 0.02, 0.03],
      [0.05, 0.4, 0.4, 0.05, 0.1],
      [0.02, 0.03, 0.05, 0.8, 0.1],
      [0.02, 0.03, 0.1, 0.1, 0.75]
    ],
    // Head 2: 语义 (processed -> robot, processed -> data)
    [
      [0.6, 0.2, 0.1, 0.05, 0.05],
      [0.2, 0.5, 0.2, 0.05, 0.05],
      [0.05, 0.35, 0.3, 0.05, 0.25],
      [0.05, 0.05, 0.1, 0.6, 0.2],
      [0.05, 0.1, 0.3, 0.1, 0.45]
    ]
  ];

  let currentStep = 2;
  let currentTokenIdx = 2; // "processed"
  let currentHead = 0;

  const svg = document.getElementById('canvas');
  const linesLayer = document.getElementById('lines-layer');
  const vectorsLayer = document.getElementById('vectors-layer');
  const tokensLayer = document.getElementById('tokens-layer');
  const labelsLayer = document.getElementById('labels-layer');
  const stepSlider = document.getElementById('step-slider');
  const stepName = document.getElementById('step-name');
  const stepInfo = document.getElementById('step-info');
  const tokenSelector = document.getElementById('token-selector');
  const headSelect = document.getElementById('head-select');

  function init() {
    // 初始化词元选择器
    tokens.forEach((t, i) => {
      const btn = document.createElement('button');
      btn.className = `token-btn ${i === currentTokenIdx ? 'active' : ''}`;
      btn.textContent = t;
      btn.onclick = () => {
        currentTokenIdx = i;
        updateUI();
      };
      tokenSelector.appendChild(btn);
    });

    stepSlider.oninput = (e) => {
      currentStep = parseInt(e.target.value);
      updateUI();
    };

    headSelect.onchange = (e) => {
      currentHead = parseInt(e.target.value);
      updateUI();
    };

    updateUI();
  }

  function updateUI() {
    stepName.textContent = steps[currentStep].name;
    stepInfo.textContent = steps[currentStep].desc;

    // 更新按钮状态
    Array.from(tokenSelector.children).forEach((btn, i) => {
      btn.className = `token-btn ${i === currentTokenIdx ? 'active' : ''}`;
    });

    render();
  }

  function render() {
    linesLayer.innerHTML = '';
    vectorsLayer.innerHTML = '';
    tokensLayer.innerHTML = '';
    labelsLayer.innerHTML = '';

    const startX = 100;
    const gap = 120;
    const tokenY = 380;
    const vectorY = 280;
    const scoreY = 160;
    const outputY = 60;

    // 绘制词元
    tokens.forEach((t, i) => {
      const x = startX + i * gap;

      // Token Box
      const g = document.createElementNS('http://www.w3.org/2000/svg', 'g');
      g.setAttribute('class', `node ${i === currentTokenIdx ? 'c-amber' : 'c-gray'}`);

      const rect = document.createElementNS('http://www.w3.org/2000/svg', 'rect');
      rect.setAttribute('x', x - 45);
      rect.setAttribute('y', tokenY - 20);
      rect.setAttribute('width', 90);
      rect.setAttribute('height', 40);
      rect.setAttribute('rx', 8);
      rect.setAttribute('stroke-width', i === currentTokenIdx ? 1.5 : 0.5);

      const text = document.createElementNS('http://www.w3.org/2000/svg', 'text');
      text.setAttribute('x', x);
      text.setAttribute('y', tokenY);
      text.setAttribute('class', 'th');
      text.setAttribute('text-anchor', 'middle');
      text.setAttribute('dominant-baseline', 'central');
      text.textContent = t;

      g.appendChild(rect);
      g.appendChild(text);
      tokensLayer.appendChild(g);

      // 步骤 1: 输入嵌入
      if (currentStep >= 1) {
        drawVector(x, vectorY, i === currentTokenIdx ? 'Q' : 'K', i === currentTokenIdx ? 'c-amber' : 'c-blue');

        const line = document.createElementNS('http://www.w3.org/2000/svg', 'line');
        line.setAttribute('x1', x);
        line.setAttribute('y1', tokenY - 20);
        line.setAttribute('x2', x);
        line.setAttribute('y2', vectorY + 25);
        line.setAttribute('class', 'arr');
        line.setAttribute('marker-end', 'url(#arrow)');
        line.setAttribute('opacity', '0.3');
        linesLayer.appendChild(line);
      }

      // 步骤 2 & 3: 注意力连线
      if (currentStep >= 2) {
        const weight = attentionMaps[currentHead][currentTokenIdx][i];
        const line = document.createElementNS('http://www.w3.org/2000/svg', 'path');
        const qX = startX + currentTokenIdx * gap;
        const kX = x;

        // 贝塞尔曲线连接 Query 到各个 Key
        const d = `M ${qX} ${vectorY - 25} C ${qX} ${scoreY}, ${kX} ${scoreY}, ${kX} ${vectorY - 25}`;
        line.setAttribute('d', d);
        line.setAttribute('fill', 'none');
        line.setAttribute('stroke', 'var(--color-text-info)');
        line.setAttribute('stroke-width', weight * 10 + 0.5);
        line.setAttribute('opacity', Math.max(0.1, weight * 1.2));
        line.setAttribute('class', 'attn-line');
        linesLayer.appendChild(line);

        // 显示权重数值
        if (currentStep === 2 || currentStep === 3) {
            const label = document.createElementNS('http://www.w3.org/2000/svg', 'text');
            label.setAttribute('x', kX);
            label.setAttribute('y', scoreY - 10);
            label.setAttribute('class', 'ts');
            label.setAttribute('text-anchor', 'middle');
            label.setAttribute('fill', 'var(--color-text-info)');
            label.textContent = weight.toFixed(2);
            labelsLayer.appendChild(label);
        }
      }

      // 步骤 4: 输出
      if (currentStep >= 4) {
        drawVector(x, outputY, 'Z', 'c-teal');
        const line = document.createElementNS('http://www.w3.org/2000/svg', 'line');
        line.setAttribute('x1', x);
        line.setAttribute('y1', vectorY - 25);
        line.setAttribute('x2', x);
        line.setAttribute('y2', outputY + 25);
        line.setAttribute('class', 'arr');
        line.setAttribute('marker-end', 'url(#arrow)');
        line.setAttribute('opacity', '0.3');
        linesLayer.appendChild(line);
      }
    });

    // 绘制图例
    if (currentStep >= 1) {
        const legendY = 20;
        drawLegend(480, legendY, 'c-amber', 'Query (查询)');
        drawLegend(580, legendY, 'c-blue', 'Key (键)');
    }
  }

  function drawVector(x, y, label, colorClass) {
    const g = document.createElementNS('http://www.w3.org/2000/svg', 'g');
    g.setAttribute('class', `vector-box ${colorClass}`);

    const rect = document.createElementNS('http://www.w3.org/2000/svg', 'rect');
    rect.setAttribute('x', x - 20);
    rect.setAttribute('y', y - 25);
    rect.setAttribute('width', 40);
    rect.setAttribute('height', 50);
    rect.setAttribute('rx', 4);
    rect.setAttribute('stroke-width', 0.5);

    // 模拟向量内部的小格子
    for(let i=0; i<3; i++) {
        const line = document.createElementNS('http://www.w3.org/2000/svg', 'line');
        line.setAttribute('x1', x - 12);
        line.setAttribute('y1', y - 10 + i*10);
        line.setAttribute('x2', x + 12);
        line.setAttribute('y2', y - 10 + i*10);
        line.setAttribute('stroke', 'currentColor');
        line.setAttribute('opacity', '0.2');
        g.appendChild(line);
    }

    const text = document.createElementNS('http://www.w3.org/2000/svg', 'text');
    text.setAttribute('x', x + 25);
    text.setAttribute('y', y);
    text.setAttribute('class', 'ts');
    text.setAttribute('style', 'font-weight:500');
    text.textContent = label;

    g.appendChild(rect);
    g.appendChild(text);
    vectorsLayer.appendChild(g);
  }

  function drawLegend(x, y, colorClass, textStr) {
    const g = document.createElementNS('http://www.w3.org/2000/svg', 'g');
    g.setAttribute('class', colorClass);
    const r = document.createElementNS('http://www.w3.org/2000/svg', 'rect');
    r.setAttribute('x', x); r.setAttribute('y', y); r.setAttribute('width', 12); r.setAttribute('height', 12); r.setAttribute('rx', 2);
    const t = document.createElementNS('http://www.w3.org/2000/svg', 'text');
    t.setAttribute('x', x + 18); t.setAttribute('y', y + 10); t.setAttribute('class', 'ts');
    t.textContent = textStr;
    g.appendChild(r); g.appendChild(t);
    labelsLayer.appendChild(g);
  }

  init();
</script>
